from pathlib import Path
import base64
import gzip
import subprocess

PAYLOAD = """"""
patch = gzip.decompress(base64.b64decode(PAYLOAD))
path = Path('.development/v0.26.3/console-fidelity.patch')
path.parent.mkdir(parents=True, exist_ok=True)
path.write_bytes(patch)
subprocess.check_call(['git','apply','--check','--whitespace=nowarn',str(path)])
subprocess.check_call(['git','apply','--whitespace=nowarn',str(path)])
path.unlink()
